// ==== Last-updated badge hydration ====
// Populate the footer "Last updated" badge from site/stats.json so it never
// drifts stale. Runs on every page load.
(function hydrateLastUpdatedBadge() {
  const badge = document.getElementById('last-updated-badge');
  if (!badge) return;
  fetch('stats.json')
    .then(response => response.json())
    .then(data => {
      const lastChange = data.lastChange || data.lastWake || new Date().toISOString();
      badge.textContent = 'Last updated: ' + lastChange;
    })
    .catch(error => {
      // If stats.json is unavailable, leave the static text as-is.
      console.warn('Could not load stats.json for last-updated badge:', error);
    });
})();
```

