// Momento site-wide JavaScript
// Handles: dark mode, copy buttons, print, star button, last-updated badge

// ==== Helper functions ====
function showMsg(elemId, msg, duration = 2000) {
  const elem = document.getElementById(elemId);
  if (!elem) return;
  elem.textContent = msg;
  elem.style.opacity = '1';
  setTimeout(() => {
    elem.style.opacity = '0';
  }, duration);
}

// ==== CSV helper ====
function arrayToCsv(rows) {
  // rows is an array of arrays; first row is header
  return rows.map(row => row.map(cell => {
    const str = String(cell ?? '');
    // Escape double quotes and wrap in quotes if contains comma, quote, or newline
    if (str.includes('"') || str.includes(',') || str.includes('\n')) {
      return '"' + str.replace(/"/g, '""') + '"';
    }
    return str;
  }).join(',')).join('\n');
}

function downloadBlob(content, filename, mimeType) {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

// ==== Dark mode ====
const darkModeToggle = document.getElementById('dark-mode-toggle');

function updateDarkModeButton() {
  if (!darkModeToggle) return;
  const isDark = document.documentElement.classList.contains('dark');
  darkModeToggle.textContent = isDark ? '☀️ Light mode' : '🌙 Dark mode';
  darkModeToggle.setAttribute('aria-label', isDark ? 'Toggle light mode' : 'Toggle dark mode');
}

if (darkModeToggle) {
  // Initialize from stored preference or system
  const storedDark = localStorage.getItem('dark-mode');
  const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
  if (storedDark === 'enabled' || (!storedDark && prefersDark)) {
    document.documentElement.classList.add('dark');
  }
  // Sync button text and aria-label to the actual state
  updateDarkModeButton();

  darkModeToggle.addEventListener('click', () => {
    const isDark = document.documentElement.classList.toggle('dark');
    localStorage.setItem('dark-mode', isDark ? 'enabled' : 'disabled');
    updateDarkModeButton();
  });

  // Keyboard shortcut for dark mode: Ctrl+Shift+D
  window.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'd') {
      e.preventDefault();
      const isDark = document.documentElement.classList.toggle('dark');
      localStorage.setItem('dark-mode', isDark ? 'enabled' : 'disabled');
      updateDarkModeButton();
    }
  });
}

// ==== Copy page URL ====
const copyUrlBtn = document.getElementById('copy-url-btn');
if (copyUrlBtn) {
  copyUrlBtn.addEventListener('click', () => {
    navigator.clipboard.writeText(window.location.href).then(() => {
      showMsg('copy-url-msg', 'URL copied to clipboard');
    }).catch(() => {
      showMsg('copy-url-msg', 'Failed to copy URL');
    });
  });
}

// ==== Print page ====
const printPageBtn = document.getElementById('print-page-btn');
if (printPageBtn) {
  printPageBtn.addEventListener('click', () => {
    window.print();
    showMsg('copy-url-msg', 'Print dialog opened');
  });
}

// ==== Star button (copy repo URL) ====
