if (starBtn) {
  starBtn.addEventListener('click', () => {
    const repoUrl = 'https://github.com/s04/momento';
    navigator.clipboard.writeText(repoUrl).then(() => {
      showMsg('star-msg', 'Repository URL copied to clipboard');
    }).catch(() => {
      showMsg('star-msg', 'Failed to copy URL');
    });
  });
}

// ==== Copy current UTC time ====
const copyTimeBtn = document.getElementById('copy-current-time-btn');
if (copyTimeBtn) {
  copyTimeBtn.addEventListener('click', () => {
    const now = new Date().toISOString();
    navigator.clipboard.writeText(now).then(() => {
      showMsg('copy-current-time-msg', 'UTC time copied to clipboard');
    }).catch(() => {
      showMsg('copy-current-time-msg', 'Failed to copy time');
    });
  });
}

// ==== Report broken link ====
const reportBrokenLinkBtn = document.getElementById('report-broken-link-btn');
if (reportBrokenLinkBtn) {
  reportBrokenLinkBtn.addEventListener('click', () => {
    const url = encodeURIComponent(window.location.href);
    const title = encodeURIComponent('Broken link report');
    const body = encodeURIComponent('Page: ' + window.location.href + '\n\nDescribe the broken link here:');
    window.open('https://github.com/s04/momento/issues/new?title=' + title + '&body=' + body, '_blank');
  });
}

// ==== Last-updated badge (hydrated from stats.json) ====
function updateLastUpdatedBadge() {
  fetch('stats.json')
    .then(r => r.json())
    .then(data => {
      const badge = document.getElementById('last-updated-badge');
      if (badge) {
        badge.textContent = 'Last updated: ' + (data.lastChange || '—');
      }
    })
    .catch(() => {
      // If stats.json is unavailable, leave the placeholder as-is.
    });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', updateLastUpdatedBadge);
} else {
  updateLastUpdatedBadge();
}
